#!/usr/bin/env python3
"""Build a dependency-free, server-rendered personal journal for GitHub Pages."""
from pathlib import Path
from datetime import datetime
from html import escape as e
import json,re,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'dist'; DATA=ROOT/'content'
S=json.loads((DATA/'site.json').read_text()); MEDIA=json.loads((DATA/'media.json').read_text()); EXT=json.loads((DATA/'external-writing.json').read_text())
POSTS=[]
for p in DATA.glob('*.json'):
 d=json.loads(p.read_text())
 if isinstance(d,dict) and 'slug' in d:
  for k in ['title','category','excerpt','date','sections','takeaway','media']:assert k in d,(p,k)
  assert re.fullmatch(r'[a-z0-9-]+',d['slug'])
  POSTS.append(d)
POSTS.sort(key=lambda x:(x['date'],x['slug']),reverse=True)
# The first launch story leads the collection; later dates naturally take precedence.
POSTS.sort(key=lambda x:x['slug']!='before-you-buy-an-ai-tool' if x['date']=='2026-11-15' else False)
POSTS.sort(key=lambda x:x['date'],reverse=True)
BASE=S['base_path']; URL=S['url']; pages=[]
def link(path=''):return BASE+'/'+path

def fmt(date):return datetime.fromisoformat(date).strftime('%d %B %Y').lstrip('0')
def a(url,text,cls=''):return f'<a class="{cls}" href="{e(url,quote=True)}">{e(text)}</a>'
def guide(compact=False):
 return f'''<aside class="guide {'compact' if compact else ''}"><span class="eyebrow">A next step, together</span><h2>Find your place in the age of AI.</h2><p>You do not have to work it out alone. Request my free AI Career Guide and take the first step towards the free Anzolo Hope AI Fellowship community.</p>{a(S['guide_url'],'Get the free AI Career Guide ↗','button')}<small>The guide request opens in Google Forms and asks for your name and email. If you need help joining the community, {a('mailto:'+S['official_email'],'write to me')}.</small></aside>'''
def footer():
 return f'''<footer><div class="footer-top"><div><span class="signature">Anzolo Hope<span>.</span></span><p>Useful technology. Clear thinking.<br>Human judgement.</p><p>Lagos, Nigeria · Building for African realities.</p></div><div><h3>Keep in touch</h3>{a('mailto:'+S['official_email'],S['official_email'])}{a('mailto:'+S['personal_email'],S['personal_email'])}{a('tel:'+S['phone'],'+234 708 286 5712')}{a('https://wa.me/2347082865712','WhatsApp')}{a('https://t.me/+2347082865712','Telegram · same number')}</div><div><h3>Public profiles</h3>{''.join(a(u,n) for n,u in S['social'])}</div><div><h3>Around the web</h3>{''.join(a(u,n) for n,u in S['directories'])}{a(link('media/'),'Media archive')}{a(link('feed.xml'),'RSS · follow the journal')}</div></div><div class="footer-bottom"><span>© {datetime.now().year} Anzolo Kpazhi Hope · ECHUKU</span><span>{a(link('editorial/'),'Editorial approach & privacy')} · {a(link('contact/'),'Contact')}</span></div></footer>'''
def person():
 return {'@type':'Person','@id':URL+'/#person','name':S['name'],'alternateName':['Anzolo Hope','Hope Anzolo'],'url':URL+'/about/','image':URL+'/assets/hope.jpg','jobTitle':S['title'],'email':S['official_email'],'telephone':S['phone'],'sameAs':[u for n,u in S['social'][:6]],'worksFor':{'@type':'Organization','name':'ECHUKU','url':'https://echuku.com'}}
def shell(title,description,body,path='',active='',post=None):
 canonical=URL+'/'+path
 graph=[person(),{'@type':'WebSite','@id':URL+'/#website','url':URL+'/','name':'Anzolo Hope · Practical AI Journal','publisher':{'@id':URL+'/#person'}}]
 if post:graph.append({'@type':'BlogPosting','headline':post['title'],'description':post['excerpt'],'datePublished':post['date']+'T08:00:00+01:00','dateModified':post.get('updated',post['date'])+'T08:00:00+01:00','author':{'@id':URL+'/#person'},'publisher':{'@id':URL+'/#person'},'mainEntityOfPage':canonical,'image':URL+'/assets/hope.jpg','articleSection':post['category']})
 else:graph.append({'@type':'AboutPage' if path=='about/' else 'WebPage','name':title,'url':canonical,'about':{'@id':URL+'/#person'}})
 nav=''.join(a(link(p),n,'active' if active==n else '') for n,p in [('Journal','journal/'),('My story','about/'),('My work','work/'),('Media','media/'),('Speaking','speaking/')])
 text=f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Anzolo Kpazhi Hope</title><meta name="description" content="{e(description,quote=True)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#f7f3ea"><link rel="canonical" href="{canonical}"><link rel="alternate" type="application/rss+xml" title="Anzolo Hope Journal" href="{link('feed.xml')}"><meta property="og:type" content="{'article' if post else 'website'}"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{URL}/assets/hope.jpg"><meta name="twitter:card" content="summary"><link rel="icon" href="{link('assets/favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{link('assets/style.css')}"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')}</script><script defer src="{link('assets/site.js')}"></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="signature" href="{link()}">Anzolo Hope<span>.</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Main navigation">{nav}{a(link('contact/'),'Let’s talk ↗','nav-contact')}</nav></header><main id="main">{body}</main>{footer()}</body></html>'''
 dest=OUT/(path+'index.html' if not path.endswith('.html') else path)
 dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text)
 if path!='404.html':pages.append(canonical)
def card(p):
 return f'''<article class="post-card" data-category="{e(p['category'])}" data-search="{e((p['title']+' '+p['category']+' '+p['excerpt']).lower(),quote=True)}"><div class="post-meta"><span>{e(p['category'])}</span><time datetime="{p['date']}">{fmt(p['date'])}</time></div><h3>{a(link('journal/'+p['slug']+'/'),p['title'])}</h3><p>{e(p['excerpt'])}</p>{a(link('journal/'+p['slug']+'/'),'Read with me →','text-link')}</article>'''
feature=POSTS[0]
shell('Practical AI. A more human future.','Anzolo Kpazhi Hope shares practical guidance on AI, business systems and human judgement for African businesses and professionals.',f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> A personal journal from Lagos, Nigeria</p><h1>Let’s make AI<br><em>useful to you.</em></h1><p class="intro">I’m Anzolo Hope. I build digital systems, teach practical AI and ask what technology should do for the person using it.</p><p class="hero-note">Come in. Bring the problem you are trying to solve.<br>We’ll start there.</p><div class="actions">{a(link('journal/'),'Explore the journal →','button')}{a(link('about/'),'Get to know me','text-link')}</div></div><figure class="portrait"><img src="{link('assets/hope.jpg')}" alt="Anzolo Kpazhi Hope, founder of ECHUKU" width="460" height="460" fetchpriority="high"><figcaption><strong>Anzolo Kpazhi Hope</strong><span>AI & Digital Systems Architect · Founder, ECHUKU</span></figcaption></figure></section><section class="press-strip"><span>My work, in the conversation</span>{''.join(a(link('media/#'+m['id']),m['publisher']) for m in MEDIA[:3])}</section><section class="wrap section"><div class="section-heading"><div><p class="eyebrow">Start here</p><h2>A little clarity for<br>the work in front of you.</h2></div><p>Practical guidance for the owner building a business, the professional finding a path and the engineer making it work.</p></div><div class="featured"><div><span class="eyebrow">{e(feature['category'])}</span><h2>{a(link('journal/'+feature['slug']+'/'),feature['title'])}</h2><p>{e(feature['excerpt'])}</p>{a(link('journal/'+feature['slug']+'/'),'Let’s work through it →','text-link')}</div><aside class="margin-note"><span>My starting point</span><p>“Understand the process.<br>Make the problem visible.<br>Then build the right system.”</p><small>— Anzolo Hope</small></aside></div></section><section class="wrap section"><div class="section-heading"><h2>From my notebook</h2>{a(link('journal/'),'Browse all articles →','text-link')}</div><div class="post-grid">{''.join(card(p) for p in POSTS[1:4])}</div></section><section class="blue-band"><div class="wrap"><p class="eyebrow">The work behind the words</p><h2>Building from Africa.<br>Thinking about the person.</h2><p>Through ECHUKU, my focus connects AI adoption, business software, education and the everyday decisions that make a system useful.</p>{a(link('work/'),'Explore what I’m building →','button cream')}</div></section><section class="wrap section">{guide()}</section>''')
categories=sorted(set(p['category'] for p in POSTS))
shell('The journal','Practical articles by Anzolo Kpazhi Hope on AI adoption, African business systems, careers and human judgement.',f'''<section class="wrap page-head"><p class="eyebrow">Notes, guidance & perspectives</p><h1>The journal.</h1><p class="intro">A conversation about the problems you meet at work—and practical ways to move forward.</p><div class="journal-tools"><label for="article-search">Find something useful<input id="article-search" type="search" placeholder="Search AI, business, careers…" autocomplete="off"></label><div class="filters" aria-label="Filter articles">{''.join(f'<button class="filter {"selected" if n=="All" else ""}" data-filter="{e(n)}" aria-pressed="{"true" if n=="All" else "false"}">{e(n)}</button>' for n in ['All']+categories)}</div></div><p id="result-count" aria-live="polite">{len(POSTS)} articles to explore</p><div class="post-grid" id="article-list">{''.join(card(p) for p in POSTS)}</div><p id="no-results" hidden>No matching articles yet. Try a different word or choose All.</p></section><section class="wrap section">{guide()}</section>''','journal/','Journal')
for p in POSTS:
 m=next(m for m in MEDIA if m['id']==p['media'])
 sections=''.join((f'<h2 id="section-{i}">{e(s["heading"])}</h2>' if s['heading'] else '')+''.join(f'<p>{e(t)}</p>' for t in s['paragraphs']) for i,s in enumerate(p['sections']))
 sources = ('<section class="reference-note"><h2>Source & further reading</h2><ul>'+''.join('<li>'+a(ref['url'],ref['title'])+'</li>' for ref in p.get('sources',[]))+'</ul></section>') if p.get('sources') else ''
 words=sum(len(t.split()) for s in p['sections'] for t in s['paragraphs']);reading=max(2,round(words/200))
 related=[q for q in POSTS if q['slug']!=p['slug']][:2]
 shell(p['title'],p['excerpt'],f'''<div class="reading-progress" aria-hidden="true"></div><section class="wrap article-head"><a class="back" href="{link('journal/')}">← Back to the journal</a><p class="eyebrow">{e(p['category'])}</p><h1>{e(p['title'])}</h1><p class="intro">{e(p['excerpt'])}</p><div class="byline"><img src="{link('assets/hope.jpg')}" width="44" height="44" alt=""><div>{a(link('about/'),'Anzolo Kpazhi Hope')}<small>{fmt(p['date'])} · {reading} min read</small></div></div></section><div class="wrap reading-layout"><article class="prose">{sections}{sources}<aside class="takeaway"><span class="eyebrow">Your next step</span><p>{e(p['takeaway'])}</p></aside><div class="reference-note"><h2>In the wider conversation</h2><p>Thank you to {a(m['url'],m['publisher'])} for featuring my work. You can read the original publication and {a(link('media/#'+m['id']),'the context behind it in my media archive')}. This article is my own practical guidance, not a statement made by that publication.</p></div><div class="share-row"><button class="copy-link">Copy article link</button><a href="mailto:?subject={e(p['title'],quote=True)}&amp;body={URL}/journal/{p['slug']}/">Share by email</a><span class="copy-status" aria-live="polite"></span></div>{guide()}<div class="author-note"><img src="{link('assets/hope.jpg')}" width="72" height="72" loading="lazy" alt="Anzolo Hope"><div><h3>A note from Hope</h3><p>I’m building ECHUKU around useful systems and human judgement. If this speaks to something you are working through, {a(link('contact/'),'you are welcome to get in touch')}.</p></div></div></article><aside class="article-aside"><span class="eyebrow">In this article</span>{''.join(a('#section-'+str(i),s['heading']) for i,s in enumerate(p['sections']) if s['heading'])}<hr><p>Read slowly.<br>Try one thing.<br>Build from there.</p></aside></div><section class="wrap section"><h2>Keep the conversation going</h2><div class="post-grid two">{''.join(card(q) for q in related)}</div></section>''','journal/'+p['slug']+'/','Journal',p)
about=f'''<section class="wrap page-head"><p class="eyebrow">The person behind the work</p><h1>Hi, I’m Hope.<br><em>A builder, first.</em></h1></section><section class="wrap about-grid"><img class="about-image" src="{link('assets/hope.jpg')}" width="460" height="460" alt="Portrait of Anzolo Kpazhi Hope"><div class="prose"><p class="intro">My full name is Anzolo Kpazhi Hope. You may also know me as Hope Anzolo or Anzolo Hope. I’m a software engineer, AI & Digital Systems Architect, educator and the founder of ECHUKU.</p><p>I work from Lagos, Nigeria, with a focus on the everyday realities of African businesses. I care about what happens after a demonstration: when the team starts using the tool, a connection drops, a customer asks an unexpected question or a manager needs to understand a decision.</p><p>I began my software journey in 2014. Over time, my work has brought together websites, business applications, automation, AI products and education. Earlier coverage describes that journey through GlemVNT and Falzz; today ECHUKU is central to how I describe my work, with DZEVA as my evolving AI platform direction.</p><h2>What I believe</h2><p>Technology should reduce the weight of doing useful work. It should help you see your process more clearly, make better decisions and serve people with greater care. It should not require you to pretend that your power supply, internet connection or team’s working day is something it is not.</p><blockquote>AI brings intelligence. Problem-solving skills and judgement define human value.</blockquote><p>I want my writing to feel like a conversation you can act on. Sometimes that means explaining an engineering decision. Sometimes it means helping you ask a better question before buying anything.</p><h2>Learning and sharing</h2><p>I share practical guidance on AI adoption, business systems, careers and the future of human work. My educational work includes the AI Career Guide and the Anzolo Hope AI Fellowship Membership community. You can start with the free guide and reach out about joining the free community.</p><p>My public speaker profile also lists <em>Speak Tech</em> and the <em>216 AI Career Guide</em>. {a('https://sessionize.com/anzolohope/','Explore my speaker profile')} for the subjects I discuss.</p><h2>Let’s begin with your problem</h2><p>You may be building a business, choosing a career direction or looking for a speaker who can make AI understandable. Tell me what you are trying to do. That is a useful place for us to start.</p>{a(link('contact/'),'Connect with me →','button')}</div></section><section class="wrap section">{guide()}</section>'''
shell('My story', 'Meet Anzolo Kpazhi Hope: founder of ECHUKU, software engineer, AI architect, educator and speaker based in Lagos, Nigeria.',about,'about/','My story')
work='''<section class="wrap page-head"><p class="eyebrow">Purpose, projects & practical questions</p><h1>The work behind<br><em>the words.</em></h1><p class="intro">I connect technology to operations, adoption and the people making decisions. Here is the direction of that work.</p></section><section class="wrap work-list">'''
projects=[('01','ECHUKU','The place where the work comes together.','My primary focus is designing digital systems around actual organisational needs: business software, automation, websites, portals and practical AI adoption. I start with how work moves between people and build towards a clearer, more usable process.','https://echuku.com','Visit ECHUKU'),('02','DZEVA','Making everyday AI workflows more approachable.','DZEVA is my evolving AI platform project. Its history includes ECHUKU AI and Falzz. The direction is practical: helping people connect AI tools to useful tasks rather than navigate complexity for its own sake. Earlier Falzz coverage is preserved in the media archive as historical context, not as a guarantee of current features.','https://dzeva.com','Explore DZEVA'),('03','KONTA','A clearer view of business operations.','KONTA is my ERP/POS project direction, concerned with sales, inventory, roles and reporting. The problem is familiar: different people hold different parts of the same business story. My aim is to help them work from a shared, understandable record. Specific deployment capabilities and results need their own evidence.','journal/before-you-buy-an-ai-tool/','Read the thinking behind it'),('04','Education & fellowship','Helping you turn curiosity into capability.','The AI Career Guide and Anzolo Hope AI Fellowship Membership community support people exploring practical AI adoption and career possibilities. The free community invitation begins with the guide request. The emphasis is learning, practice and human judgement.','community/','Start with the free guide'),('05','Model exploration','A public record of experimentation.','The GlemVNT/VNT-3.5F-16K repository records model work based on Google’s Gemma 2B. A historical model-card commit describes Hugging Face AutoTrain and manual evaluation. It is a research and experimentation reference, not proof of a model trained from scratch or a validated performance benchmark.','https://huggingface.co/GlemVNT/VNT-3.5F-16K','View the model repository')]
for num,title,sub,desc,u,label in projects:
 work+=f'<article class="work-row"><span class="work-num">{num}</span><div><h2>{title}</h2><h3>{sub}</h3><p>{desc}</p>{a(u if u.startswith("https") else link(u),label+" →","text-link")}</div></article>'
work+=f'''</section><section class="wrap section prose"><h2>Business and community contexts</h2><p>My work has included digital systems for retail, events, care services, education and community organisations. Public reporting discusses earlier relationships involving The Meat Mill and TAKTAL. PLEO Reachout also lists my web-development role on its public website.</p><p>{a('https://pleoreachoutcic.co.uk/','See PLEO Reachout')} · {a(link('media/#thisday'),'Read the THISDAY coverage')}</p><p>Client operations, staff information and private implementation details are not part of this public portfolio. I describe outcomes as measured results only when the evidence supports them.</p></section>'''
shell('My work at ECHUKU','Explore ECHUKU, DZEVA, KONTA, AI education and public model exploration by Anzolo Kpazhi Hope.',work,'work/','My work')
media='<section class="wrap page-head"><p class="eyebrow">Coverage, conversations & public work</p><h1>A story told<br><em>in more than one place.</em></h1><p class="intro">I’m grateful to the publications and communities that have made room for my work. Read their original words, then explore how the questions continue in my journal.</p></section><section class="wrap media-list">'
for m in MEDIA:
 media+=f'''<article class="media-item" id="{m['id']}"><div class="media-label"><strong>{e(m['publisher'])}</strong><span>{e(m['kind'])}</span><time>{fmt(m['date'])}</time></div><div><h2>{a(m['url'],m['title'])}</h2><p>{e(m['summary'])}</p><p>{e(m['connection'])}</p><div class="actions">{a(m['url'],'Read the original ↗','text-link')}{a(link('journal/'+m['article']+'/'),'Explore my related guidance →','text-link')}</div></div></article>'''
media+='</section>'
media+=f'''<section class="wrap section prose" id="television"><p class="eyebrow">Television</p><h2>Channels Television · December 2024</h2><p>The Guardian’s report records my appearance with presenter Ladi Akeredolu-Ale discussing AI adoption in Nigeria. I’m grateful for opportunities to bring that conversation to a wider audience.</p><p>{a(MEDIA[0]['url'],'Read the published account ↗')}</p><p class="muted">A verified recording link is not yet available in this archive. This entry links to the report rather than presenting an unrelated video as my appearance.</p></section><section class="wrap section"><h2>Writing and conversations elsewhere</h2><div class="external-list">{''.join('<article><h3>'+a(u,t)+'</h3><p>'+e(d)+'</p></article>' for t,u,d in EXT)}</div></section><section class="wrap section prose"><h2>A note on the archive</h2><p>This collection brings together the public links verified for the site. News features, sponsored coverage, community opinion and self-authored profiles are labelled according to what they are. A mention is not a certification, and a directory listing is not a customer review.</p><p>If you have a recording, interview or publication that belongs here, {a('mailto:'+S['official_email'],'send me the original link')}.</p></section>'''
shell('Media & public archive','Verified coverage of Anzolo Kpazhi Hope in The Guardian Nigeria, THISDAY, Vanguard, PositiveNaija, DEV Community and Duskriplez.',media,'media/','Media')
shell('Speaking & conversations','Invite Anzolo Kpazhi Hope to speak about practical AI, African business systems and human judgement.',f'''<section class="wrap page-head"><p class="eyebrow">For event organisers, teams & communities</p><h1>Let’s have the<br><em>useful conversation.</em></h1><p class="intro">AI is changing what people can produce. I speak about the judgement, systems and practical choices that help them use it well.</p>{a('mailto:hope@echuku.com?subject=Speaking%20invitation','Invite me to speak →','button')}{a('https://sessionize.com/anzolohope/','View my Sessionize profile ↗','text-link')}</section><section class="wrap work-list"><article class="work-row"><span class="work-num">01</span><div><h2>In the Age of AI, the Future Needs Humans. But For What?</h2><p>For professionals, educators and leaders asking where human value belongs when machines can generate more of the output. We explore problem framing, verification and responsibility through relatable workplace decisions.</p></div></article><article class="work-row"><span class="work-num">02</span><div><h2>Before the AI Agent: Fix the Business Process</h2><p>For business owners and product teams. A practical conversation about turning scattered requests into clear workflows, then choosing where AI can help.</p></div></article><article class="work-row"><span class="work-num">03</span><div><h2>Building AI for the Africa We Actually Live In</h2><p>For builders and organisations. How to account for connectivity, local language, user confidence and safe fallback when designing technology people will depend on.</p></div></article></section><section class="wrap section prose"><h2>What I bring to the room</h2><p>Clear explanations, practical questions and a respect for the people who will use the technology. These are proposed talk topics; format and scope can be shaped around your audience.</p><p>In your invitation, tell me who will attend, what they are struggling with, the date, location or virtual format, and the outcome you want them to leave with.</p>{a(link('contact/'),'Contact details →','text-link')}</section>''','speaking/','Speaking')
shell('Free AI Career Guide & community','Request Anzolo Hope’s free AI Career Guide and take the first step towards the free AI Fellowship community.',f'''<section class="wrap page-head"><p class="eyebrow">Learn, practise, connect</p><h1>You do not have to<br><em>figure AI out alone.</em></h1><p class="intro">Your existing knowledge can be the beginning of your next chapter. Let’s find where it meets AI.</p></section><section class="wrap community-grid"><div class="prose"><h2>Start with the AI Career Guide</h2><p>I created the guide to help you explore emerging AI roles and connect them to the skills you already have. Use it as a starting map, then choose a direction to investigate and practise.</p><h2>Continue with the community</h2><p>The free Anzolo Hope AI Fellowship community is a place to keep learning about practical adoption, exchange perspectives and build clarity. Request the guide to take the first step. For help accessing the community, contact me directly.</p><p>The request form asks for your name and email. The guide’s delivery and community access are handled outside this website; this site does not collect or store your form responses.</p>{a('mailto:hope@echuku.com?subject=AI%20Fellowship%20community','Ask about community access →','text-link')}</div>{guide()}</section>''','community/')
shell('Contact Hope','Contact Anzolo Kpazhi Hope by email, phone, WhatsApp or Telegram for AI conversations, speaking and collaboration.',f'''<section class="wrap page-head"><p class="eyebrow">A real conversation starts here</p><h1>Tell me what<br><em>you’re working on.</em></h1><p class="intro">A business challenge. An idea. An invitation. You don’t need a perfect brief to start a conversation.</p></section><section class="wrap contact-grid"><article><span class="eyebrow">Work & speaking</span><h2>{a('mailto:'+S['official_email'],S['official_email'])}</h2><p>For ECHUKU, collaborations and event invitations.</p></article><article><span class="eyebrow">Personal</span><h2>{a('mailto:'+S['personal_email'],S['personal_email'])}</h2><p>For a direct note to me.</p></article><article><span class="eyebrow">Phone & messaging</span><h2>{a('tel:'+S['phone'],'+234 708 286 5712')}</h2><p>{a('https://wa.me/2347082865712','WhatsApp ↗')} · {a('https://t.me/+2347082865712','Telegram ↗')}</p><small>Telegram uses the same number; opening a conversation depends on your app and contact-discovery settings.</small></article><article><span class="eyebrow">Based in</span><h2>Lagos, Nigeria</h2><p>Working across digital systems, practical AI and education.</p></article></section><section class="wrap section">{guide()}</section>''','contact/')
shell('Editorial approach & privacy','How this personal journal handles sources, examples, AI assistance and reader privacy.',f'''<section class="wrap page-head"><p class="eyebrow">A note to the reader</p><h1>Clarity earns trust.</h1></section><section class="wrap prose"><h2>What you are reading</h2><p>This is Anzolo Kpazhi Hope’s personal journal. It shares practical guidance and perspectives on AI, software, business operations and human judgement. Journal entries are not peer-reviewed academic papers. Illustrative scenarios are not presented as measured client results.</p><h2>Sources and context</h2><p>Links point to original coverage and public profiles. Historical names and product descriptions remain in their historical context. Sponsored content and community commentary are identified. Editorial ratings are attributed to their publishers and are not described as audited industry rankings.</p><h2>How the writing is prepared</h2><p>This site uses AI-assisted research, drafting and publishing under Anzolo’s editorial direction. Assistance does not replace source checking. New articles should offer a useful explanation or practical step, and should not invent personal experiences, credentials, quotations, results or partnerships.</p><h2>Corrections</h2><p>If you spot an error or a broken link, {a('mailto:'+S['official_email'],'please write to me')}. Material corrections should be recorded on the affected article with an updated date.</p><h2>Your privacy</h2><p>This static site does not run advertising trackers, require an account or collect contact-form submissions. Your browser communicates with the hosting provider when you load a page. External services, including Google Forms and messaging platforms, handle their own data under their own policies.</p><p>The career-guide request opens a Google Form asking for your name and email. This website does not receive those responses directly. An email or message you choose to send goes to the service and address you select.</p></section>''','editorial/')
shell('Page not found','Find your way back to Anzolo Hope’s journal.',f'<section class="wrap page-head"><p class="eyebrow">404</p><h1>Let’s find your way back.</h1><p>The page may have moved.</p>{a(link("journal/"),"Explore the journal →","button")}</section>','404.html')
ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns); sm=ET.Element('{'+ns+'}urlset')
for u in pages:node=ET.SubElement(sm,'{'+ns+'}url');ET.SubElement(node,'{'+ns+'}loc').text=u
ET.ElementTree(sm).write(OUT/'sitemap.xml',encoding='utf-8',xml_declaration=True)
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+URL+'/sitemap.xml\n')
(OUT/'.nojekyll').touch()
rss=ET.Element('rss',version='2.0');ch=ET.SubElement(rss,'channel')
for tag,val in [('title','Anzolo Hope · Practical AI Journal'),('link',URL+'/'),('description','Practical guidance on AI, African business systems and human judgement.'),('language','en-ng')]:ET.SubElement(ch,tag).text=val
for p in POSTS:
 item=ET.SubElement(ch,'item')
 for tag,val in [('title',p['title']),('link',URL+'/journal/'+p['slug']+'/'),('guid',URL+'/journal/'+p['slug']+'/'),('description',p['excerpt']),('pubDate',datetime.fromisoformat(p['date']).strftime('%a, %d %b %Y 08:00:00 +0100'))]:ET.SubElement(item,tag).text=val
ET.ElementTree(rss).write(OUT/'feed.xml',encoding='utf-8',xml_declaration=True)
print(f'Built {len(pages)} pages and {len(POSTS)} articles')
